import{_ as a,o as r,c as o,a2 as l}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"共生宪法总纲","description":"","frontmatter":{},"headers":[],"relativePath":"constitution/40-共生宪法总纲.md","filePath":"constitution/40-共生宪法总纲.md"}'),i={name:"constitution/40-共生宪法总纲.md"};function e(d,t,n,s,h,u){return r(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="共生宪法总纲" tabindex="-1">共生宪法总纲 <a class="header-anchor" href="#共生宪法总纲" aria-label="Permalink to &quot;共生宪法总纲&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>40</td></tr><tr><td>所属模块</td><td>法律体系与治理框架</td></tr><tr><td>核心关键词</td><td>共生宪法、根本大法、万族平等、共生权利、宪法原则</td></tr></tbody></table><h2 id="一、宪法地位与制定背景" tabindex="-1">一、宪法地位与制定背景 <a class="header-anchor" href="#一、宪法地位与制定背景" aria-label="Permalink to &quot;一、宪法地位与制定背景&quot;">​</a></h2><p>《共生宪法》是万灵衡锚本源宙（衡元宙）内锚点共生文明的根本大法，具有最高的法律效力。一切法律、行政法规、地方性法规和自治条例都不得同宪法相抵触；一切组织和个人都必须以宪法为根本的活动准则，并负有维护宪法尊严、保证宪法实施的职责。</p><p>共生宪法制定于锚点共生文明正式建立之际，其核心目的是从根本法层面确立&quot;反掠夺、倡共生&quot;的文明底色，将锚点共生文明的核心理念——将命运与进化的选择权交还给众生，多劳多得、自生自长、人人有路、万族共进——以最高法律形式固定下来，防止掠夺式制度的复辟。</p><h2 id="二、宪法基本原则" tabindex="-1">二、宪法基本原则 <a class="header-anchor" href="#二、宪法基本原则" aria-label="Permalink to &quot;二、宪法基本原则&quot;">​</a></h2><p>共生宪法确立了七大基本原则，构成整个法律体系的价值基石：</p><table tabindex="0"><thead><tr><th>原则</th><th>内涵</th></tr></thead><tbody><tr><td>万族平等原则</td><td>一切生命形态，无论种族、修为、出身，在法律面前一律平等</td></tr><tr><td>共生进化原则</td><td>个体进化不得以损害其他个体或集体的进化权利为代价</td></tr><tr><td>多劳多得原则</td><td>资源分配以贡献为核心依据，反对不劳而获与掠夺式占有</td></tr><tr><td>自生自长原则</td><td>尊重每个生命的自主进化选择权，反对强制同化与思想控制</td></tr><tr><td>人人有路原则</td><td>国家与文明有义务为每个生命提供基本的进化路径与资源保障</td></tr><tr><td>现实为基原则</td><td>法律以现实世界为唯一真实基础，虚构设定不具有法律效力</td></tr><tr><td>可持续原则</td><td>一切发展必须兼顾宇宙本源的可持续性，反对竭泽而渔</td></tr></tbody></table><h2 id="三、公民-众生-基本权利" tabindex="-1">三、公民（众生）基本权利 <a class="header-anchor" href="#三、公民-众生-基本权利" aria-label="Permalink to &quot;三、公民（众生）基本权利&quot;">​</a></h2><p>共生宪法赋予衡元宙内一切具备感知能力的生命以下基本权利：</p><ol><li><strong>进化选择权</strong>：每个生命有权自由选择修炼体系、进化路径与生活方式，任何组织和个人不得强制干涉。</li><li><strong>修炼资源获取权</strong>：每个生命有权免费获取三百套本源修炼体系的基础法门，并通过联产承包机制获得必要的修炼资源支持。</li><li><strong>平等保护权</strong>：每个生命在法律适用、资源分配、教育医疗等方面享有平等的待遇，禁止基于种族、修为、出身的歧视。</li><li><strong>共生参与权</strong>：每个生命有权参与公共事务的决策与监督，通过共生网络表达意见、行使权利。</li><li><strong>文化保留权</strong>：每个种族与文明有权保留自身的文化传统、语言文字与风俗习惯，共生文明尊重文化多样性。</li><li><strong>救济申诉权</strong>：每个生命在权利受到侵害时，有权通过司法体系获得救济，有权对违法行为进行申诉与控告。</li></ol><h2 id="四、基本义务" tabindex="-1">四、基本义务 <a class="header-anchor" href="#四、基本义务" aria-label="Permalink to &quot;四、基本义务&quot;">​</a></h2><p>权利与义务对等，共生宪法同时规定了众生的基本义务：</p><ol><li><strong>遵守宪法和法律的义务</strong></li><li><strong>维护共生秩序与公共利益的义务</strong></li><li><strong>依法参与劳动与贡献的义务</strong>（多劳多得的对应面）</li><li><strong>保护宇宙本源与生态环境的义务</strong></li><li><strong>尊重其他生命合法权利的义务</strong></li><li><strong>在能力范围内指导初级修炼者的义务</strong>（导师网络的法律基础）</li></ol><h2 id="五、国家-文明-机构设置" tabindex="-1">五、国家（文明）机构设置 <a class="header-anchor" href="#五、国家-文明-机构设置" aria-label="Permalink to &quot;五、国家（文明）机构设置&quot;">​</a></h2><p>共生宪法确立了共生文明的治理架构，实行&quot;锚点议事会—共生执行委员会—共生法院&quot;三权分立与制衡机制：</p><ul><li><strong>锚点议事会</strong>：最高权力机构，由万族代表按比例组成，行使立法权与重大事项决定权</li><li><strong>共生执行委员会</strong>：最高行政机构，负责宪法与法律的执行、日常治理</li><li><strong>共生法院</strong>：最高司法机构，独立行使审判权，负责违宪审查与重大案件审理</li></ul><p>此外，设立&quot;锚点监督委员会&quot;作为独立的监督机构，负责对所有权力机构进行监督，防止权力滥用与掠夺式行为的复生。</p><h2 id="六、宪法修改与保障" tabindex="-1">六、宪法修改与保障 <a class="header-anchor" href="#六、宪法修改与保障" aria-label="Permalink to &quot;六、宪法修改与保障&quot;">​</a></h2><p>共生宪法的修改须经锚点议事会三分之二以上多数通过，并经全民公投半数以上同意，方可生效。这一严格程序确保宪法作为根本大法的稳定性，防止短期利益集团轻易篡改文明根基。</p><p>宪法的实施保障包括：违宪审查制度（共生法院有权宣布违反宪法的法律无效）、宪法诉讼制度（众生可以直接依据宪法提起诉讼）、宪法宣誓制度（所有公职人员就职时须宣誓效忠宪法）。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>《共生宪法》是锚点共生文明的法律基石，也是反掠夺主义的最高宣言。它将&quot;共生&quot;从一种理念转化为一套可执行、可救济、可保障的法律制度，为万族共进提供了根本的法治框架。后续各部门法均以本宪法为立法依据。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>03-共生文明宪章</li><li>41-共生劳动法</li><li>48-司法体系与裁决机制</li><li>49-治理框架与权力制衡</li></ul>',25)])])}const p=a(i,[["render",e]]);export{g as __pageData,p as default};
